import Foundation

/// Independent pinned source NumPy reference must be generated by
/// ios/scripts/build80_original_raw_tint_oracle.py before running.
enum Build80OriginalRAWTintValidation {
    enum Failure: LocalizedError {
        case invalid(String)
        var errorDescription: String? {
            if case .invalid(let message) = self { return message }
            return nil
        }
    }

    static func evaluate() throws {
        guard let path=ProcessInfo.processInfo.environment[
            "BUILD80_RAW_TINT_ORACLE"
        ] else {
            print("UNVERIFIED Build80 source RAW tint: oracle path absent")
            return
        }
        let json=try Data(contentsOf:URL(fileURLWithPath:path))
        guard let root=try JSONSerialization.jsonObject(with:json)
                as? [String:Any],
              root["source_git_blob_sha"] as? String ==
                "97e34feb80fe47a6a3b36fcb93bef626d397135a",
              let inputs=root["input_bits"] as? [NSNumber],
              inputs.count==18,
              let cases=root["cases"] as? [[String:Any]],
              cases.count==6 else {
            throw Failure.invalid("Build80 RAW tint Python oracle malformed")
        }
        let image=inputs.map { Float(bitPattern:$0.uint32Value) }
        var checked=0
        for item in cases {
            let tint:Double?
            if item["tint"] is NSNull {
                tint=nil
            } else if let numeric=item["tint"] as? NSNumber {
                tint=numeric.doubleValue
            } else {
                throw Failure.invalid("RAW tint oracle case missing tint")
            }
            guard let expected=item["expected_bits"] as? [NSNumber],
                  expected.count==image.count else {
                throw Failure.invalid("RAW tint expected Float32 bits missing")
            }
            let actual=try Build80OriginalRAWTint.apply(image,tint:tint)
            for i in image.indices {
                let a=actual[i].bitPattern
                let b=expected[i].uint32Value
                guard a==b else {
                    throw Failure.invalid(
                        "Pinned original NumPy vs native Swift RAW tint "
                        + "mismatch case \(checked) channel \(i): "
                        + "0x\(String(a,radix:16)) != 0x\(String(b,radix:16))"
                    )
                }
            }
            checked+=1
        }
        do {
            _=try Build80OriginalRAWTint.apply([0.1,0.2],tint:1.5)
            throw Failure.invalid("Malformed RAW tint RGB input accepted")
        } catch Build80OriginalRAWTint.Failure.invalid {
            // Correct boundary rejection.
        }
        print("PASS Build80 pinned Python RAW tint vs Swift Float32 "
              + "\(checked*image.count)/\(checked*image.count) exact "
              + "channel bits across \(checked) cases; NOT demosaic/ACES parity")
    }
}
